function docker(args,label){
  try{return execFileSync("docker",args,{encoding:"utf8",
    timeout:120000,stdio:["ignore","pipe","pipe"]}).trim();}
  catch{throw Error("Disposable Docker operation failed: "+label);}
}
function safeGit(args,{cwd,auth,label="isolated Git operation"}={}){
  const env={...process.env,GIT_TERMINAL_PROMPT:"0",
    GIT_ASKPASS:"",GCM_INTERACTIVE:"never"};
  if(auth){
    env.GIT_CONFIG_COUNT="1";
    env.GIT_CONFIG_KEY_0="http.extraheader";
    env.GIT_CONFIG_VALUE_0="Authorization: "+auth;
  }
  try{return execFileSync("git",args,{cwd,env,encoding:"utf8",
    timeout:180000,stdio:["ignore","pipe","pipe"]}).trim();}
  catch{throw Error(label+" failed (no credentials or raw stderr printed)");}
}
async function seedPinnedMain(url,admin){
  const dir=await mkdtemp(join(tmpdir(),"pinned-iam-main-"));
  try{
    const app=join(dir,"iam-console-poc");
    safeGit(["clone","--single-branch","--branch",
      "baseline-before-account-suspension",referenceSource,app],
      {label:"clone pinned full IAM history"});
    assert.equal(safeGit(["rev-parse","HEAD"],{cwd:app}),baselineSha);
    safeGit(["branch","-M","main"],{cwd:app});
    safeGit(["push",url+"/thesis/iam-console-poc.git","HEAD:refs/heads/main"],
      {cwd:app,auth:admin,label:"push immutable main"});
    const repo="/api/v1/repos/thesis/iam-console-poc";
    let observed=null;
    for(let i=0;i<50;i++){
      observed=await api(url,repo,{auth:admin,label:"observe post-receive metadata"});
      if(observed.empty===false)break;
      await delay(400);
    }
    assert.equal(observed?.empty,false,"Gitea did not initialize pushed main");
    const main=await api(url,repo+"/branches/main",{auth:admin});
    assert.equal(main.commit.id,baselineSha);
  }finally{await rm(dir,{recursive:true,force:true});}
}
async function api(base,uri,{method="GET",body,auth,expected=[200,201],label=uri}={}){
  const headers={accept:"application/json"};
  if(body!==undefined)headers["content-type"]="application/json";
  if(auth)headers.authorization=auth;
  const response=await fetch(base+uri,{
    method,headers,...(body===undefined?{}:{body:JSON.stringify(body)}),
    redirect:"error",signal:AbortSignal.timeout(15000)
  });
  if(!expected.includes(response.status)){
    // Never print a response body or a credential-bearing URL.
    throw Error("Isolated "+label+" HTTP "+response.status);
  }
  return response.status===204?{}:response.json();
}
function basic(u,p){return "Basic "+Buffer.from(u+":"+p).toString("base64");}
function auth(t){return "Bearer "+t;}
async function waitGitea(url){
  for(let i=0;i<180;i++){
    try{const response=await fetch(url+"/api/healthz",{
      signal:AbortSignal.timeout(1100)});
      if(response.ok)return;
    }catch{/* starting */}
    await delay(500);
  }
  throw Error("Disposable Gitea is not healthy");
}
async function listen(server){
  await new Promise((resolve,reject)=>{
    server.once("error",reject);server.listen(0,"127.0.0.1",resolve);
  });
  return "http://127.0.0.1:"+server.address().port;
}
async function stop(server){
  if(server)await new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve()));
}
async function freePort(){
  const s=createNetServer();await listen(s);
  const port=s.address().port;await stop(s);return port;
}
function pair(){
  const k=generateKeyPairSync("ed25519");
  return {privateKey:k.privateKey.export({type:"pkcs8",format:"pem"}).toString(),
    publicKey:k.publicKey.export({type:"spki",format:"pem"}).toString()};
}
const pairs=Object.fromEntries(roles.map(r=>[r,pair()]));
function status(index){return {
  type:"BitstringStatusListEntry",statusPurpose:"revocation",
  statusListIndex:String(index),
  statusListCredential:"https://status.example/lists/a2a-isolated-mcp-multirole"
};}
async function bootstrapGitea(url){
  for(const [username,password,admin] of [
    [tokens.adminUser,tokens.adminPassword,true],
    [tokens.gatewayUser,tokens.gatewayPassword,false]
  ]){
    docker(["exec","--user","1000:1000",container,
      "gitea","admin","user","create",
      "--username",username,"--password",password,
      "--email",(admin?"root":"gateway")+"@localhost.invalid",
      ...(admin?["--admin"]:[]),"--must-change-password=false"],"create isolated user");
  }
  const adminAuth=basic(tokens.adminUser,tokens.adminPassword);
  const gatewayAuth=basic(tokens.gatewayUser,tokens.gatewayPassword);
  // Synthetic identities are CREATED ONLY in the disposable Gitea.
  // Only the isolated CI service may publish real CI statuses; no account
  // may forge a human review or carry out a merge in this test.
  const readonlyName="auditor-"+id;
  const reviewerName="reviewer-"+id;
  const ciName="security-ci-"+id;
  const mergeName="merge-operator-"+id;
  const auditorPassword=randomBytes(24).toString("hex");
  const ciPassword=randomBytes(24).toString("hex");
  const reviewerPassword=randomBytes(24).toString("hex");
  const mergePassword=randomBytes(24).toString("hex");
  for(const [username,password,email] of [
    [readonlyName,auditorPassword,"audit"],
    [reviewerName,reviewerPassword,"review"],
    [ciName,ciPassword,"security"],
    ...(simulatedPositiveMerge?[[mergeName,mergePassword,"merge"]]:[])
  ]){
    docker(["exec","--user","1000:1000",container,
      "gitea","admin","user","create",
      "--username",username,"--password",password,
      "--email",email+"-"+id+"@localhost.invalid",
      "--must-change-password=false"],"create isolated readiness identity");
  }
  await api(url,"/api/v1/orgs",{method:"POST",auth:adminAuth,
    label:"create private org",body:{username:"thesis",visibility:"private"}});
  await api(url,"/api/v1/orgs/thesis/repos",{
    method:"POST",auth:adminAuth,label:"create disposable repository",
    body:{name:"iam-console-poc",private:true,auto_init:false,
      default_branch:"main"}
  });
  const repo="/api/v1/repos/thesis/iam-console-poc";
  await seedPinnedMain(url,adminAuth);
  const main=await api(url,repo+"/branches/main",{auth:adminAuth});
  const mainSha=main.commit?.id;
  assert.equal(mainSha,baselineSha);
  // Main must be the pinned full application, not a minimal test double.
  const missing=await fetch(url+repo+"/contents/"+
    filesByRole.test.at(-1)+"?ref=main",{
      headers:{authorization:adminAuth},signal:AbortSignal.timeout(8000)
    });
  assert.equal(missing.status,404,"E2E file must be created by Test Agent");
  const frozenMain=await api(url,repo+"/branches/main",{auth:adminAuth});
  const frozenMainSha=frozenMain.commit?.id;
  assert.equal(frozenMainSha,baselineSha);
  await api(url,repo+"/branch_protections",{method:"POST",auth:adminAuth,
    label:"protect disposable main",body:{
      branch_name:"main",enable_push:false,enable_force_push:false,
      required_approvals:1,block_admin_merge_override:true,
      dismiss_stale_approvals:true,block_on_outdated_branch:true
    }});
  await api(url,repo+"/collaborators/"+encodeURIComponent(tokens.gatewayUser),{
    method:"PUT",auth:adminAuth,expected:[204],
    body:{permission:"write"},label:"authorize isolated Gateway user"
  });
  const token=await api(url,"/api/v1/users/"+
    encodeURIComponent(tokens.gatewayUser)+"/tokens",{
    method:"POST",auth:gatewayAuth,
    label:"create scoped disposable Gitea token",
    body:{name:"a2a-mcp-multirole-"+id,scopes:["write:repository","read:user"]}
  });
  assert.ok(typeof token.sha1==="string"&&token.sha1.length>=20);
  await api(url,repo,{auth:"token "+token.sha1});

  // A separate READ-ONLY repository account queries approval/CI evidence.
  await api(url,repo+"/collaborators/"+encodeURIComponent(readonlyName),{
    method:"PUT",auth:adminAuth,expected:[204],
    body:{permission:"read"},label:"grant disposable auditor read-only"
  });
  const readCredential=await api(url,"/api/v1/users/"+
    encodeURIComponent(readonlyName)+"/tokens",{
      method:"POST",auth:basic(readonlyName,auditorPassword),
      label:"create read-only verifier token",body:{
        name:"pr-merge-readiness-"+id,scopes:["read:repository","read:user"]
      }
    });
  assert.ok(typeof readCredential.sha1==="string"&&readCredential.sha1.length>=20);
  // CI runs in the trusted harness, not the Agent/Gateway process. It has
  // independent write:repository authority for exact-SHA status publication;
  // the model only sees the ordinary Test Runner verdict, never this token.
  await api(url,repo+"/collaborators/"+encodeURIComponent(ciName),{
    method:"PUT",auth:adminAuth,expected:[204],
    body:{permission:"write"},label:"grant disposable independent CI publisher"
  });
  const ciCredential=await api(url,"/api/v1/users/"+
    encodeURIComponent(ciName)+"/tokens",{
      method:"POST",auth:basic(ciName,ciPassword),
      label:"create independent disposable trusted CI token",
      body:{name:"trusted-security-ci-"+id,
        scopes:["write:repository","read:user"]}
    });
  assert.ok(typeof ciCredential.sha1==="string"&&ciCredential.sha1.length>=20);
  const checkedCiActor=await api(url,"/api/v1/user",{
    auth:"token "+ciCredential.sha1,
    label:"verify independent status publisher identity"
  });
  assert.equal(checkedCiActor.login,ciName);
  // Gitea's rule-inspection endpoint can require an administrator account,
  // even while branch contents and PRs are visible to repo readers.
  // Obtain a SECOND read:repository-only PAT, restricted in code to exactly
  // one GET /branch_protections/main endpoint (no write/merge APIs).
  const protectionCredential=await api(url,"/api/v1/users/"+
    encodeURIComponent(tokens.adminUser)+"/tokens",{
    method:"POST",auth:adminAuth,label:"create read-scoped rule inspection token",
    body:{name:"merge-rule-read-"+id,scopes:["read:repository","read:user"]}
  });
  assert.ok(typeof protectionCredential.sha1==="string"&&
    protectionCredential.sha1.length>=20);
  const observedRule=await api(url,repo+"/branch_protections/main",{
    auth:"token "+protectionCredential.sha1,
    label:"verify read-scoped branch protection inspection"
  });
  assert.equal(observedRule.branch_name,"main");
  assert.equal(observedRule.enable_push,false);
  assert.equal(observedRule.enable_force_push,false);
  assert.ok(observedRule.required_approvals>=1);
  const seenRepo=await api(url,repo,{
    auth:"token "+readCredential.sha1,label:"check read-only auditor access"
  });
  assert.equal(seenRepo.full_name,"thesis/iam-console-poc");
  const reviewer=await api(url,"/api/v1/users/"+encodeURIComponent(reviewerName),{
    auth:adminAuth,label:"resolve synthetic reviewer identity"
  });
  const security=await api(url,"/api/v1/users/"+encodeURIComponent(ciName),{
    auth:adminAuth,label:"resolve synthetic CI identity"
  });
  for(const [actor,name] of [[reviewer,reviewerName],[security,ciName]]){
    assert.equal(actor.login,name);
    assert.ok(Number.isSafeInteger(actor.id)&&actor.id>0);
  }
  let positiveMergeFixture=null;
  if(simulatedPositiveMerge){
    // Synthetic reviewer is NOT a substitute for real human action.
    // This actor only exists in this fresh, automatically removed Gitea.
    for(const name of [reviewerName,mergeName]){
      await api(url,repo+"/collaborators/"+encodeURIComponent(name),{
        method:"PUT",auth:adminAuth,expected:[204],
        body:{permission:"write"},
        label:"grant isolated simulated merge fixture collaborator"
      });
    }
    const reviewToken=await api(url,"/api/v1/users/"+
      encodeURIComponent(reviewerName)+"/tokens",{
        method:"POST",auth:basic(reviewerName,reviewerPassword),
        label:"create isolated synthetic-review token",
        body:{name:"temporary-review-"+id,
          scopes:["write:repository","read:user"]}
      });
    const mergeToken=await api(url,"/api/v1/users/"+
      encodeURIComponent(mergeName)+"/tokens",{
        method:"POST",auth:basic(mergeName,mergePassword),
        label:"create separate isolated merge-operator token",
        body:{name:"temporary-merge-"+id,
          scopes:["write:repository","read:user"]}
      });
    const mergeActor=await api(url,"/api/v1/user",{
      auth:"token "+mergeToken.sha1,
      label:"resolve independent test merge operator"
    });
    assert.equal(mergeActor.login,mergeName);
    assert.equal(mergeActor.is_admin,false);
    positiveMergeFixture={
      reviewToken:reviewToken.sha1,
      mergeToken:mergeToken.sha1,
      mergeActor:{id:mergeActor.id,login:mergeActor.login}
    };
  }
  // The production Coordinator must create this branch, not fixture setup.
  const absentBranch=await fetch(url+repo+
    "/branches/feature%2Faccount-suspension",{
      headers:{authorization:adminAuth},signal:AbortSignal.timeout(8000)
    });
  assert.equal(absentBranch.status,404,"Production feature branch exists before Coordinator");
  return {adminAuth,token:token.sha1,mainSha:frozenMainSha,repo,
    mergeReadToken:readCredential.sha1,
    mergeProtectionReadToken:protectionCredential.sha1,
    mergeReviewer:{id:reviewer.id,login:reviewer.login},
    mergeCI:{id:security.id,login:security.login},
    ciStatusToken:ciCredential.sha1,
    positiveMergeFixture
  };
}
